using Domain;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Infrastructure.Configurations
{
    public class GeoCityConfiguration : IEntityTypeConfiguration<GeoCity>
    {
        public void Configure(EntityTypeBuilder<GeoCity> builder)
        {
            builder.HasKey(g => g.Id);

            builder.Property(g => g.Id)
                .HasColumnName("ID")
                .ValueGeneratedOnAdd();

            builder.Property(g => g.City)
                .IsRequired()
                .HasColumnType("text")
                .HasColumnName("City");

            builder.Property(g => g.State)
                .IsRequired()
                .HasColumnType("text")
                .HasColumnName("State");

            // UserInput = true marks records created from unrecognised user submissions
            // so admins can review and delete them without affecting curated data.
            builder.Property(g => g.UserInput)
                .IsRequired()
                .HasDefaultValue(false)
                .HasColumnName("UserInput");

            // Unique composite — a (City, State) pair must appear only once.
            // Used by GeoService for O(1) lookup on every business signup.
            builder.HasIndex(g => new { g.City, g.State })
                .IsUnique()
                .HasDatabaseName("IX_L50_City_State");

            builder.ToTable("L50_Geo_Cities");


            #region SEED DATA   
